const fs=require('fs'),assert=require('assert/strict'),png=require('./scripts/png.cjs');const dir=fs.readFileSync('latest-all-hair-sync-path.txt','utf8')+'/',before=JSON.parse(fs.readFileSync(dir+'before.json')),p=structuredClone(before),changes=[],records=[],maps={7:{front:202,rear:0},9:{front:204,rear:1},10:{front:206,rear:2},11:{front:208,rear:3}};
const dec=c=>png.decode(Buffer.from(c.dataURL.split(',')[1],'base64'));
function world(c){const im=dec(c),r=c.placement||{x:0,y:0},data=new Uint8Array(64*64*4);assert(!c.placement||(c.placement.w===im.width&&c.placement.h===im.height));for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++){const i=(y*im.width+x)*4;if(!im.data[i+3])continue;const xx=x+r.x,yy=y+r.y;assert(xx>=0&&yy>=0&&xx<64&&yy<64,'existing off-canvas hair requires inspection');data.set(im.data.subarray(i,i+4),(yy*64+xx)*4);}return {width:64,height:64,data};}
function box(im){let x0=99,y0=99,x1=-1,y1=-1;for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++)if(im.data[(y*im.width+x)*4+3]){x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);}return x1<0?null:{x0,y0,x1,y1,cx:(x0+x1)/2,w:x1-x0+1,h:y1-y0+1};}
function head(si,ai,fi){const k=`${si}_${ai}_${fi}`,l=p.layers.find(l=>l.sheetIndex===si&&l.name==='head'&&l.frameData[k]);assert(l,k+' missing head');const b=box(world(l.frameData[k]));assert(b);return b;}
function phases(si,ai){const a=p.spriteSheets[si].actions[ai],ys=a.frames.map((_,i)=>head(si,ai,i).y0);if(si===7){assert.deepEqual(ys.map(y=>y-Math.min(...ys)),[0,2,2,0,0,2,2,0]);return [1,2,3,0,1,2,3,0];}if(si!==9){assert.equal(ys.length,4);assert.equal(ys[0],ys[1]);assert.equal(ys[2],ys[3]);return [0,1,2,3];}const out=[0];for(let i=1;i<ys.length;i++)out.push(ys[i]>ys[i-1]?2:ys[i]<ys[i-1]?0:out[i-1]===2?3:out[i-1]===0?1:out[i-1]);return out;}
for(const si of [7,9,10,11])for(let ai=0;ai<p.spriteSheets[si].actions.length;ai++){const action=p.spriteSheets[si].actions[ai],sai=p.spriteSheets[8].actions.findIndex(a=>a.direction===action.direction),phase=phases(si,ai);assert(sai>=0);for(let fi=0;fi<action.frames.length;fi++){const sf=phase[fi],sh=head(8,sai,sf),th=head(si,ai,fi);assert.equal(th.w,sh.w,'head width differs, requires pose-specific design');assert.equal(th.h,sh.h,'head shape differs, requires pose-specific design');const dx=th.cx-sh.cx,dy=th.y0-sh.y0;assert(Number.isInteger(dx));for(const slot of ['front','rear']){const sourceLayer=slot==='front'?198:11,li=maps[si][slot],key=`${si}_${ai}_${fi}`,c=p.layers[li].frameData[key];assert(c,key+' missing '+slot);const old=dec(c),placement=c.placement||{x:0,y:0},src=world(before.layers[sourceLayer].frameData[`8_${sai}_${sf}`]),sb=box(src),tb=box(world(c)),out=new Uint8Array(old.data.length);assert.equal(p.layers[li].sheetIndex,si);let tail=null,sj=null,tj=null;if(sb){if(slot==='rear'){assert(tb);tail=tb.y1;sj=sh.y0+12;tj=th.y0+12;assert(tail>tj&&sb.y1>sj);}for(let y=0;y<old.height;y++)for(let x=0;x<old.width;x++){const wx=x+placement.x,wy=y+placement.y,sx=wx-dx,sy=slot==='rear'&&wy>tj?sj+Math.round((wy-tj)*(sb.y1-sj)/(tail-tj)):wy-dy;if(sx<0||sx>=64||sy<0||sy>=64||(slot==='rear'&&wy>tail))continue;out.set(src.data.subarray((sy*64+sx)*4,(sy*64+sx)*4+4),(y*old.width+x)*4);}
 const result=box({width:old.width,height:old.height,data:out});assert(result,key+' empty');assert.equal(result.y0+placement.y,th.y0,'hair root must align to actual head');if(slot==='rear')assert.equal(result.y1+placement.y,tail,'preserve existing fitted tail endpoint');else{for(let sy=0;sy<64;sy++)for(let sx=0;sx<64;sx++){const i=(sy*64+sx)*4;if(!src.data[i+3])continue;const x=sx+dx-placement.x,y=sy+dy-placement.y;assert(x>=0&&y>=0&&x<old.width&&y<old.height,'front fringe would be clipped '+key);assert.deepEqual([...out.subarray((y*old.width+x)*4,(y*old.width+x)*4+4)],[...src.data.subarray(i,i+4)]);}}}else assert(slot==='front'&&action.direction==='up');
 let n=0,mask=0;for(let i=0;i<out.length;i+=4){if([0,1,2,3].some(k=>out[i+k]!==old.data[i+k]))n++;if(out[i+3]!==old.data[i+3])mask++;}if(n){c.dataURL='data:image/png;base64,'+png.encode(old.width,old.height,out).toString('base64');changes.push({layer:li,key,pixels:n,maskPixels:mask});}records.push({key,slot,sourceLayer,source:`8_${sai}_${sf}`,dx,dy,tail,head:[th.x0,th.y0,th.x1,th.y1]});}}}
const restore=structuredClone(p);for(const c of changes)restore.layers[c.layer].frameData[c.key]=before.layers[c.layer].frameData[c.key];assert.deepEqual(restore,before,'only mapped hair cels may change');assert.deepEqual(p.spriteSheets,before.spriteSheets);assert.deepEqual(p.layers.filter(l=>l.sheetIndex===8),before.layers.filter(l=>l.sheetIndex===8),'idle source must stay exact');for(let i=0;i<7;i++)assert.deepEqual(p.layers.filter(l=>l.sheetIndex===i),before.layers.filter(l=>l.sheetIndex===i));fs.writeFileSync(dir+'restore-extra-copy.json',JSON.stringify(restore));assert.deepEqual(JSON.parse(fs.readFileSync(dir+'restore-extra-copy.json')),before);fs.writeFileSync(dir+'candidate.json',JSON.stringify(p));fs.writeFileSync(dir+'diff.json',JSON.stringify({changes,records},null,2));fs.writeFileSync(dir+'verification.json',JSON.stringify({changes,updatedCels:changes.length,shapeChangedCels:changes.filter(c=>c.maskPixels>0).length,sourceLayers:{front:198,rear:11},idleExact:true,allNonHairAndMetadataExact:true,existingTargetRearTailEndpointsPreserved:true,frontSourcePixelsExactAfterHeadAlignment:true,allOriginalArchivesUnchanged:true,restoreExtraCopyVerified:true,browserChecked:false},null,2));console.log('PASS build',changes.length,'cels;',changes.filter(c=>c.maskPixels>0).length,'shape changes; head/pose anchored; idle and nonhair exact');console.log('pickup phases',records.filter(r=>r.key.startsWith('9_')&&r.slot==='front').map(r=>[r.key,r.source]));
